                        s2 = cpx*s1 + 4 * b01 *s0;
                        s2 += 4 * b00 * _gx[368];
                        _gx[464] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 5 * b01 *s0;
                        s2 += 4 * b00 * _gx[448];
                        _gx[544] = s2;
