    atomicAdd(ejk+ia*3+1, v_iy);
    atomicAdd(ejk+ia*3+2, v_iz);
    atomicAdd(ejk+ja*3+0, -(v_ix + v_jx));
    atomicAdd(ejk+ja*3+1, -(v_iy + v_jy));
    atomicAdd(ejk+ja*3+2, -(v_iz + v_jz));
