                    v_iy += (ai2 * g[30] - 1 * g[28]) * s;
                    v_ky += (ak2 * g[41]) * s;
                    v_ly += (al2 * (g[41] - ylyk * g[29])) * s;
                    s = dd[19] * (g[1] * g[48]);
                    s += dd[22] * (g[0] * g[49]);
                    v_iy += (ai2 * g[34] - 1 * g[32]) * s;
                    v_ky += (ak2 * g[45]) * s;
                    v_ly += (al2 * (g[45] - ylyk * g[33])) * s;
                    s = dd[3] * (g[8] * g[48]);
                    s += dd[15] * (g[4] * g[52]);
                    s += dd[33] * (g[0] * g[56]);
                    v_iy += (ai2 * g[27] - 2 * g[25]) * s;
                    v_ky += (ak2 * g[38]) * s;
                    v_ly += (al2 * (g[38] - ylyk * g[26])) * s;
                    s = dd[9] * (g[4] * g[48]);
                    s += dd[27] * (g[0] * g[52]);
                    v_iy += (ai2 * g[31] - 2 * g[29]) * s;
                    v_ky += (ak2 * g[42]) * s;
                    v_ly += (al2 * (g[42] - ylyk * g[30])) * s;
                    s = dd[21] * (g[0] * g[48]);
                    v_iy += (ai2 * g[35] - 2 * g[33]) * s;
                    v_ky += (ak2 * g[46]) * s;
                    v_ly += (al2 * (g[46] - ylyk * g[34])) * s;
                    s = dd[0] * (g[10] * g[24]);
                    s += dd[1] * (g[9] * g[25]);
                    s += dd[3] * (g[8] * g[26]);
                    s += dd[6] * (g[6] * g[28]);
                    s += dd[7] * (g[5] * g[29]);
                    s += dd[9] * (g[4] * g[30]);
                    s += dd[18] * (g[2] * g[32]);
                    s += dd[19] * (g[1] * g[33]);
                    s += dd[21] * (g[0] * g[34]);
                    v_iz += (ai2 * g[49]) * s;
                    v_kz += (ak2 * g[60]) * s;
                    v_lz += (al2 * (g[60] - zlzk * g[48])) * s;
                    s = dd[12] * (g[6] * g[24]);
                    s += dd[13] * (g[5] * g[25]);
                    s += dd[15] * (g[4] * g[26]);
                    s += dd[24] * (g[2] * g[28]);
                    s += dd[25] * (g[1] * g[29]);
                    s += dd[27] * (g[0] * g[30]);
                    v_iz += (ai2 * g[53]) * s;
                    v_kz += (ak2 * g[64]) * s;
                    v_lz += (al2 * (g[64] - zlzk * g[52])) * s;
                    s = dd[30] * (g[2] * g[24]);
                    s += dd[31] * (g[1] * g[25]);
                    s += dd[33] * (g[0] * g[26]);
                    v_iz += (ai2 * g[57]) * s;
                    v_kz += (ak2 * g[68]) * s;
                    v_lz += (al2 * (g[68] - zlzk * g[56])) * s;
                    s = dd[2] * (g[9] * g[24]);
                    s += dd[4] * (g[8] * g[25]);
                    s += dd[8] * (g[5] * g[28]);
                    s += dd[10] * (g[4] * g[29]);
                    s += dd[20] * (g[1] * g[32]);
                    s += dd[22] * (g[0] * g[33]);
                    v_iz += (ai2 * g[50] - 1 * g[48]) * s;
                    v_kz += (ak2 * g[61]) * s;
                    v_lz += (al2 * (g[61] - zlzk * g[49])) * s;
                    s = dd[14] * (g[5] * g[24]);
                    s += dd[16] * (g[4] * g[25]);
                    s += dd[26] * (g[1] * g[28]);
                    s += dd[28] * (g[0] * g[29]);
                    v_iz += (ai2 * g[54] - 1 * g[52]) * s;
                    v_kz += (ak2 * g[65]) * s;
                    v_lz += (al2 * (g[65] - zlzk * g[53])) * s;
                    s = dd[32] * (g[1] * g[24]);
                    s += dd[34] * (g[0] * g[25]);
                    v_iz += (ai2 * g[58] - 1 * g[56]) * s;
                    v_kz += (ak2 * g[69]) * s;
                    v_lz += (al2 * (g[69] - zlzk * g[57])) * s;
                    s = dd[5] * (g[8] * g[24]);
                    s += dd[11] * (g[4] * g[28]);
                    s += dd[23] * (g[0] * g[32]);
                    v_iz += (ai2 * g[51] - 2 * g[49]) * s;
                    v_kz += (ak2 * g[62]) * s;
                    v_lz += (al2 * (g[62] - zlzk * g[50])) * s;
                    s = dd[17] * (g[4] * g[24]);
                    s += dd[29] * (g[0] * g[28]);
                    v_iz += (ai2 * g[55] - 2 * g[53]) * s;
                    v_kz += (ak2 * g[66]) * s;
                    v_lz += (al2 * (g[66] - zlzk * g[54])) * s;
                    s = dd[35] * (g[0] * g[24]);
                    v_iz += (ai2 * g[59] - 2 * g[57]) * s;
                    v_kz += (ak2 * g[70]) * s;
                    v_lz += (al2 * (g[70] - zlzk * g[58])) * s;
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        double *ejk = jk.ejk;
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
        // translational invariance: j's derivative is minus the sum of the other three centers'
        v_jx += v_kx + v_lx;
        v_jy += v_ky + v_ly;
        v_jz += v_kz + v_lz;
