            for (int n = gout_id; n < 90; n+=4) {
                int i = n % 10;
                int j = n / 10 % 3;
                int k = n / 30 % 3;
                int l = n / 90;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _li = _l*nao+_i;
                int _ki = _k*nao+_i;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
