                    v_ly += (al2 * (vgx[1856] - ylyk * vgx[1376])) * s;
                    s = dd_cache[928] * (vgx[160] * vgx[960]);
                    s += dd_cache[1568] * (vgx[0] * vgx[1120]);
                    v_iz += (ai2 * vgx[2208] - 3 * vgx[2144]) * s;
                    v_kz += (ak2 * vgx[2656]) * s;
                    v_lz += (al2 * (vgx[2656] - zlzk * vgx[2176])) * s;
                    s = dd_cache[1888] * (vgx[0] * vgx[960]);
