                    v_ky += (ak2 * vgx[2432]) * s;
                    v_ly += (al2 * (vgx[2432] - ylyk * vgx[1920])) * s;
                    s = dd_cache[1728] * (vgx[0] * vgx[3072]);
                    v_iy += (ai2 * vgx[2496] - 2 * vgx[2368]) * s;
