                    s += dd_cache[1472] * (vgx[256] * vgx[2048]);
                    s += dd_cache[1856] * (vgx[0] * vgx[2304]);
                    v_iz += (ai2 * vgx[3264] - 2 * vgx[3136]) * s;
                    v_kz += (ak2 * vgx[3712]) * s;
                    v_lz += (al2 * (vgx[3712] - zlzk * vgx[3200])) * s;
