                    s += dd_cache[3008] * (vgx[0] * vgx[1792]);
                    v_iz += (ai2 * vgx[3776] - 2 * vgx[3648]) * s;
                    v_kz += (ak2 * vgx[4224] - 1 * vgx[3200]) * s;
                    v_lz += (al2 * (vgx[4224] - zlzk * vgx[3712])) * s;
                    s = dd_cache[1088] * (vgx[512] * vgx[1536]);
                    s += dd_cache[2240] * (vgx[0] * vgx[2048]);
                    v_iz += (ai2 * vgx[3520] - 2 * vgx[3392]) * s;
                    v_kz += (ak2 * vgx[3968]) * s;
                    v_lz += (al2 * (vgx[3968] - zlzk * vgx[3456])) * s;
                    s = dd_cache[3392] * (vgx[0] * vgx[1536]);
                    v_iz += (ai2 * vgx[4032] - 2 * vgx[3904]) * s;
                    v_kz += (ak2 * vgx[4480] - 1 * vgx[3456]) * s;
                    v_lz += (al2 * (vgx[4480] - zlzk * vgx[3968])) * s;
