            dd[4] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)] + dmb[(j0+1)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+1)] + dmb[(j0+1)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+1)*nao+(i0+1)] + dmb[(j0+1)*nao+(i0+1)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
