            dd[6] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+2)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+2)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)] + dmb[(j0+2)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+0)] + dmb[(j0+2)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+2)*nao+(i0+0)] + dmb[(j0+2)*nao+(i0+0)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
